const int g_bugcode_count = (int)(sizeof(g_bugcodes) / sizeof(g_bugcodes[0]));

const char *bugcode_lookup(uint32_t code) {
    int i;
    for (i = 0; i < g_bugcode_count; i++)
        if (g_bugcodes[i].code == code) return g_bugcodes[i].name;
    return 0;
}
